code='''from collections import Counter
def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r,row in enumerate(grid) if any(v != bg for v in row)]
    groups = []
    for r in active:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)
    for group in groups:
        r = group[-1]
        inds = [i for i,v in enumerate(grid[r]) if v != bg]
        for i in range(max(inds)+1, len(out[r])):
            out[r][i] = 1
    return out
